package com.salespunch360.mobile.ui.account.expense
import androidx.compose.foundation.clickable;import androidx.compose.foundation.layout.*;import androidx.compose.foundation.lazy.*;import androidx.compose.material.icons.Icons;import androidx.compose.material.icons.filled.*;import androidx.compose.material3.*;import androidx.compose.runtime.*;import androidx.compose.ui.Modifier;import androidx.compose.ui.unit.dp;import androidx.lifecycle.compose.collectAsStateWithLifecycle;import androidx.lifecycle.viewmodel.compose.viewModel;import com.salespunch360.mobile.*;import com.salespunch360.mobile.account.*;import kotlinx.serialization.json.*
@Composable fun ExpenseCategoryScreen(padding:PaddingValues,vm:ExpenseCategoryViewModel=viewModel()){val s=vm.state.collectAsStateWithLifecycle().value;Column(Modifier.fillMaxSize().padding(padding).padding(16.dp)){Row{OutlinedTextField(s.query,vm::search,label={Text("Search categories")},modifier=Modifier.weight(1f));IconButton(vm::load){Icon(Icons.Default.Refresh,"Refresh")};FilledIconButton({vm.edit()}){Icon(Icons.Default.Add,"New category")}};if(s.loading)LinearProgressIndicator(Modifier.fillMaxWidth());s.error?.let{Text(it,color=MaterialTheme.colorScheme.error)};LazyColumn{items(s.categories,key={it.str("id")}){x->ListItem(headlineContent={Text(x.str("name"))},supportingContent={Text("${x.str("scope")} · ${s.ledgers.firstOrNull{it.str("id")==x.str("defaultLedgerAccountId")}?.str("name").orEmpty()}")},trailingContent={if(x["isActive"]?.jsonPrimitive?.booleanOrNull==true)TextButton({vm.disable(x.str("id"))}){Text("Deactivate")}else Text("Inactive")},modifier=Modifier.clickable{vm.edit(x)})}}};s.editing?.let{CategoryEditor(it,s.ledgers,vm::close,vm::save)}}
@OptIn(ExperimentalMaterial3Api::class) @Composable private fun CategoryEditor(x:JsonObject,ledgers:List<JsonObject>,close:()->Unit,save:(JsonObject)->Unit){var name by remember{mutableStateOf(x.str("name"))};var scope by remember{mutableStateOf(x.str("scope").ifBlank{"EXPENSE"})};var ledger by remember{mutableStateOf(x.str("defaultLedgerAccountId"))};var openScope by remember{mutableStateOf(false)};var openLedger by remember{mutableStateOf(false)};AlertDialog(onDismissRequest=close,title={Text("Expense category")},text={Column(verticalArrangement=Arrangement.spacedBy(8.dp)){OutlinedTextField(name,{name=it},label={Text("Name")});ExposedDropdownMenuBox(openScope,{openScope=it}){OutlinedTextField(scope,{},readOnly=true,label={Text("Scope")},modifier=Modifier.menuAnchor());ExposedDropdownMenu(openScope,{openScope=false}){listOf("EXPENSE","INCOME","BOTH").forEach{v->DropdownMenuItem({Text(v)},{scope=v;openScope=false})}}};ExposedDropdownMenuBox(openLedger,{openLedger=it}){OutlinedTextField(ledgers.firstOrNull{it.str("id")==ledger}?.str("name").orEmpty(),{},readOnly=true,label={Text("Posting ledger")},modifier=Modifier.menuAnchor());ExposedDropdownMenu(openLedger,{openLedger=false}){ledgers.filter{scope=="BOTH"||it.str("accountClass")==scope}.forEach{v->DropdownMenuItem({Text(v.str("name"))},{ledger=v.str("id");openLedger=false})}}}}},confirmButton={Button(enabled=name.isNotBlank()&&ledger.isNotBlank(),onClick={save(buildJsonObject{put("name",name);put("scope",scope);put("defaultLedgerAccountId",ledger)})}){Text("Save")}},dismissButton={TextButton(close){Text("Cancel")}})}
